#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 4861 §4.4 neighbor advertisement for 2001:db8::2, solicited and override set, with a target link-layer address option.
    fn vector() -> Vec<u8> {
        vec![
            0x88, 0x00, 0x00, 0x00, 0x60, 0x00, 0x00, 0x00, 0x20, 0x01, 0x0d, 0xb8, 0x00, 0x00,
            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02, 0x02, 0x01, 0x00, 0x11,
            0x22, 0x33, 0x44, 0x55,
        ]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Icmpv6NdNa);
        let l = p.find_layer(ProtoId::Icmpv6NdNa).unwrap();
        assert_eq!(p.get(l, "type").unwrap(), FieldValue::Uint(136));
        assert_eq!(p.get(l, "code").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "cksum").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "R").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "S").unwrap(), FieldValue::Uint(1));
        assert_eq!(p.get(l, "O").unwrap(), FieldValue::Uint(1));
        assert_eq!(p.get(l, "res").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Icmpv6NdNa);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Icmpv6NdNa);
        let l = p.find_layer(ProtoId::Icmpv6NdNa).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Icmpv6NdNa, false, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
